#!/usr/bin/env node
/**
 * Fix Dashboard Configuration
 * Updates environment variables to use correct API endpoints
 */

import { writeFileSync, readFileSync, existsSync } from 'fs';
import { join } from 'path';

console.log('🔧 Fixing Dashboard Configuration\n');

const dashboardDir = './dashboard';
const envLocalPath = join(dashboardDir, '.env.local');
const envProductionPath = join(dashboardDir, '.env.production');

// Local development configuration
const localConfig = `# Local Development Configuration
# Generated by fix-dashboard-config.mjs

# Use relative paths for API calls (proxied through Next.js)
NEXT_PUBLIC_API_BASE=/api/control

# Control plane URL (for server-side proxy)
CONTROL_PLANE_URL=http://localhost:3000
`;

// Production configuration template
const productionConfig = `# Production Configuration
# Update CONTROL_PLANE_URL with your actual deployed URL

# Use relative paths for API calls (proxied through Next.js)
NEXT_PUBLIC_API_BASE=/api/control

# Control plane URL (update this with your Render.com URL or production domain)
CONTROL_PLANE_URL=https://your-control-plane.onrender.com
`;

try {
  // Create .env.local for local development
  writeFileSync(envLocalPath, localConfig);
  console.log('✅ Created dashboard/.env.local');
  console.log('   - API calls will use relative paths');
  console.log('   - Proxied through Next.js to http://localhost:3000\n');
  
  // Create .env.production template if it doesn't exist
  if (!existsSync(envProductionPath)) {
    writeFileSync(envProductionPath, productionConfig);
    console.log('✅ Created dashboard/.env.production');
    console.log('   ⚠️  Remember to update CONTROL_PLANE_URL with your production URL\n');
  } else {
    console.log('ℹ️  dashboard/.env.production already exists (not modified)\n');
  }
  
  // Check proxy configuration
  const proxyPath = join(dashboardDir, 'app/api/control/[...path]/route.ts');
  if (existsSync(proxyPath)) {
    console.log('✅ API proxy route exists at app/api/control/[...path]/route.ts\n');
  } else {
    console.log('⚠️  API proxy route not found - dashboard may not work correctly\n');
  }
  
  console.log('=' .repeat(60));
  console.log('\n📋 NEXT STEPS:\n');
  console.log('1. Restart your dashboard development server:');
  console.log('   cd dashboard');
  console.log('   npm run dev\n');
  
  console.log('2. Make sure control plane is running:');
  console.log('   npm run dev (in root directory)\n');
  
  console.log('3. Access dashboard at: http://localhost:3001\n');
  
  console.log('4. For production deployment:');
  console.log('   - Update dashboard/.env.production with your control plane URL');
  console.log('   - Rebuild dashboard: cd dashboard && npm run build');
  console.log('   - Deploy to Render.com or your hosting service\n');
  
} catch (error) {
  console.error('❌ Error:', error.message);
  process.exit(1);
}
